import collections
def diags(p):
    r,c=divmod(p,9); o=[]
    for dr in (-1,1):
        for dc in (-1,1):
            rr,cc=r+dr,c+dc
            if 0<=rr<9 and 0<=cc<9: o.append(rr*9+cc)
    return o
